function get_youtube_video_id_from_acf($post_id) {
    // Get the video URL from the ACF field 'media_video'
    $youtube_url = get_field('media_video', $post_id);

    if ($youtube_url) {
        // Parse the URL
        $parsed_url = parse_url($youtube_url);

        // Check if it's a valid YouTube URL
        if (isset($parsed_url['host'])) {
            if ($parsed_url['host'] === 'youtu.be') {
                // Format: youtu.be/ID
                return trim($parsed_url['path'], '/');
            } elseif (strpos($parsed_url['host'], 'youtube.com') !== false) {
                // Formats: youtube.com/watch?v=ID or youtube.com/embed/ID or youtube.com/v/ID
                if (isset($parsed_url['query'])) {
                    parse_str($parsed_url['query'], $query_vars);
                    if (isset($query_vars['v'])) {
                        return $query_vars['v'];
                    }
                }

                if (isset($parsed_url['path'])) {
                    $path_parts = explode('/', trim($parsed_url['path'], '/'));
                    if (in_array($path_parts[0], ['embed', 'v'])) {
                        return $path_parts[1];
                    }
                }
            }
        }
    }

    return false; // Return false if no valid YouTube ID is found
}

