/**
 * Version 2.0
 * Retrieves the YouTube video ID from the speaker_showreel field.
 * Returns an empty string if no valid ID is found.
 */

function get_video_id_from_page_type($post_id) {
    // Retrieve the YouTube URL from the speaker options page
    $youtube_url = get_field('speaker_showreel', 'option');

    // Check if the URL exists
    if (!$youtube_url) {
        return ''; // Return empty if no URL is found
    }

    // Extract the YouTube video ID using regex
    preg_match('/[?&]v=([^"&?\/\s]{11})/', $youtube_url, $matches);

    // Return the video ID if found, or empty if not
    return (!empty($matches) && isset($matches[1])) ? $matches[1] : '';
}

// // Function to display categories and subcategories
function display_categories($categories, $current_url, $is_parent = true) {
    foreach ($categories as $category) {
        $parent_class = $is_parent ? ' posts-menu__item--parent' : '';
        
        // Determine if the current category or subcategory should be open
        $is_current_or_subcategory = strpos($current_url, $category['permalink']) === 0;

        // Add the "open" class if the current URL matches the category permalink or any subcategory
        $open_class = $is_current_or_subcategory ? ' open' : '';
        echo '<div class="posts-menu__item' . $parent_class . $open_class . '">';
        echo '<a class="posts-menu__link" href="' . $category['permalink'] . '">' . $category['name'] . '</a>';

        // Check if the category has subcategories
        if (!empty($category['subcategories'])) {
            echo '<div class="posts-menu__subcategories" style="' . ($is_current_or_subcategory ? 'display:block;' : 'display:none;') . '">';

            // Add a link to the parent category at the top of the subcategories
            if ($is_parent) {
                echo '<div class="posts-menu__item">';
                echo '<a class="posts-menu__link" href="' . $category['permalink'] . '">All ' . $category['name'] . ' Articles</a>';
                echo '</div>';
            }

            // Recursively display subcategories
            display_categories($category['subcategories'], $current_url, false);
            echo '</div>';
        }

        echo '</div>';
    }
}


