}

/**
 * Debugging version of extractYouTubeID to check for YouTube ID extraction.
 *
 * @param string $url The YouTube URL.
 * @return string|null The YouTube ID or a debug message.
 */
function extractYouTubeID( $url ) {
    // Check for valid YouTube URL structures
    if ( preg_match( '/(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|embed)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/', $url, $matches ) ) {
        return $matches[1]; // Return the YouTube ID
    } else {
        return 'Could not extract YouTube ID from: ' . $url; // Debug message
    }
}

/**
 * Final version of get_standardized_media_url.
 * Handles both YouTube and Vimeo URLs and returns the standardized URL.
 */
function get_standardized_media_url( $url ) {
    if ( empty( $url ) ) {
        return 'URL is empty';
    }

    // Check for YouTube URL
    if ( strpos( $url, 'youtube.com' ) !== false || strpos( $url, 'youtu.be' ) !== false ) {
        $youtube_id = extractYouTubeID( $url );
        if ( $youtube_id ) {
            return 'https://www.youtube.com/watch?v=' . $youtube_id;
        } else {
            return 'YouTube ID not found in URL: ' . $url;
        }
    }

    // Check for Vimeo URL
    if ( strpos( $url, 'vimeo.com' ) !== false ) {
        if ( preg_match( '/vimeo\.com\/(?:.*#|.*)?(\d+)/', $url, $matches ) ) {
            return 'https://vimeo.com/' . $matches[1];
        } else {
            return 'Vimeo ID not found in URL: ' . $url;
        }
    }

    // If neither YouTube nor Vimeo
    return 'Unknown media type in URL: ' . $url;
}

/**
 * Debugging version to check Vimeo ID extraction.
 *
 * @param string $url The Vimeo URL.
 * @return string The extracted Vimeo ID or a debug message.
 */
function extractVimeoID( $url ) {
    if ( preg_match( '/vimeo\.com\/(\d+)/', $url, $matches ) ) {
        return 'Extracted Vimeo ID: ' . $matches[1];
    } else {
        return 'Could not extract Vimeo ID from URL: ' . $url;
    }
}

/**
 * Version 1.6
 * Function to get the highest quality thumbnail from YouTube or Vimeo.
 * Includes fallbacks for YouTube thumbnails.
 *
 * @param string $url The media URL (YouTube or Vimeo).
 * @return string The thumbnail URL or a debug message.
 */
function get_high_quality_thumbnail( $url ) {
    if ( empty( $url ) ) {
        return 'URL is empty';
    }

    // Check if the URL is a YouTube URL
    if ( strpos( $url, 'youtube.com' ) !== false || strpos( $url, 'youtu.be' ) !== false ) {
        $youtube_id = extractYouTubeID( $url );
        if ( $youtube_id ) {
            // Try to return the highest quality thumbnail
            $thumbnail_url = 'https://img.youtube.com/vi/' . $youtube_id . '/maxresdefault.jpg';

            // Check if the maxresdefault image exists
            $headers = get_headers( $thumbnail_url );
            if ( strpos( $headers[0], '200' ) === false ) {
                // Fallback to the standard resolution thumbnail
                $thumbnail_url = 'https://img.youtube.com/vi/' . $youtube_id . '/hqdefault.jpg';
            }

            return $thumbnail_url;
        } else {
            return 'YouTube ID not found';
        }
    }

    // Check if the URL is a Vimeo URL
    if ( strpos( $url, 'vimeo.com' ) !== false ) {
        if ( preg_match( '/vimeo\.com\/(\d+)/', $url, $matches ) ) {
            $vimeo_id = $matches[1];

            // Fetch Vimeo thumbnail data via API
            $vimeo_response = wp_remote_get( "https://vimeo.com/api/v2/video/$vimeo_id.json" );
            if ( ! is_wp_error( $vimeo_response ) && wp_remote_retrieve_response_code( $vimeo_response ) == 200 ) {
                $vimeo_data_body = wp_remote_retrieve_body( $vimeo_response );
                $vimeo_data_json = json_decode( $vimeo_data_body, true );
                if ( isset( $vimeo_data_json[0]['thumbnail_large'] ) ) {
                    return $vimeo_data_json[0]['thumbnail_large'];
                } else {
                    return 'Vimeo thumbnail not found in API response';
                }
            } else {
                return 'Vimeo API request failed with response code: ' . wp_remote_retrieve_response_code( $vimeo_response );
            }
        } else {
            return 'Vimeo ID not found';
        }
    }

    return 'Unknown media type';
}

