/**
 * Version 1.1
 * Get all terms (default to 'category') with their permalinks, excluding specific slugs.
 *
 * @param array $excluded_slugs - List of term slugs to exclude.
 * @param string $taxonomy - Taxonomy to use (default: 'category').
 * @return array - List of terms with their permalinks and subterms.
 */
function get_all_terms_with_permalinks($excluded_slugs = array(), $taxonomy = 'category') {
    // Prepare an array to hold our results
    $terms_info = array();

    // Get all parent terms in the specified taxonomy
    $args = array(
        'taxonomy' => $taxonomy,
        'hide_empty' => true, // Change to false if you want to get terms without posts
        'parent' => 0, // Only get top-level terms
    );
    $all_terms = get_terms($args);

    // Function to recursively get subterms
    function get_subterms($parent_id, $excluded_slugs, $taxonomy) {
        $subterms_info = array();

        $args = array(
            'taxonomy' => $taxonomy,
            'hide_empty' => true,
            'parent' => $parent_id,
        );
        $subterms = get_terms($args);

        foreach ($subterms as $subterm) {
            if (!in_array($subterm->slug, $excluded_slugs)) {
                $subterm_link = get_term_link($subterm->term_id);
                $subterms_info[] = array(
                    'name' => $subterm->name,
                    'permalink' => $subterm_link,
                    'subterms' => get_subterms($subterm->term_id, $excluded_slugs, $taxonomy),
                );
            }
        }

        return $subterms_info;
    }

    // Loop through all terms
    foreach ($all_terms as $term) {
        // Check if the current term's slug is in the excluded slugs array
        if (!in_array($term->slug, $excluded_slugs)) {
            // Get the term link
            $term_link = get_term_link($term->term_id);

            // Add the term name and link to our results array, including subterms
            $terms_info[] = array(
                'name' => $term->name,
                'permalink' => $term_link,
                'subterms' => get_subterms($term->term_id, $excluded_slugs, $taxonomy),
            );
        }
    }

    // Return the result
    return $terms_info;
}

