/**
 * Version 1.0
 * Fetches and randomizes images from the ACF repeater 'logo_section_images'.
 * Limits the output to a specified number of images (default is 10).
 */
if (!function_exists('get_random_logo_section_images')) {
    function get_random_logo_section_images($postID = null, $limit = 14) {
        // Get the current post ID if not provided
        if ($postID === null) {
            $postID = get_the_ID();
        }

        // Fetch the ACF repeater field 'logo_section_images'
        $images = get_field('logo_section_images', $postID);

        // Check if the repeater field has rows
        if ($images) {
            // Shuffle the images for randomization
            shuffle($images);

            // Limit the output to the specified number of images (default is 10)
            $images = array_slice($images, 0, $limit);

            return $images;
        }

        return [];
    }
}

