/**
 * Version 1.1
 * Retrieves the hero headline or subheadline for the current archive term.
 * If the headline field is empty, returns the term name as a fallback.
 *
 * @param string $type The type of content to retrieve ('headline' or 'subheadline').
 * @return string The content of the matching ACF options field or the term name if the field is empty.
 */
function get_current_archive_hero_content( $type ) {
    // Get the queried object to determine the current archive term
    $term_object = get_queried_object();

    if ( isset( $term_object->slug ) ) {
        $term_slug = strtolower( $term_object->slug ); // Slug should match the ACF field prefix
        $field_name = "{$term_slug}_hero_{$type}";

        // Retrieve the field value from the ACF options page
        $field_value = get_field( $field_name, 'option' );

        // If field value is empty and type is 'headline', fallback to term name
        if ( $type === 'headline' && empty( $field_value ) ) {
            return ucwords( str_replace( '-', ' ', $term_object->name ) ); // Return formatted term name
        }

        return $field_value ? $field_value : '';
    }

    return ''; // Return empty if no term is found
}

/**
 * Version 1.2
 * Retrieves the URL to navigate back to the archive term page.
 *
 * @param string $return_type The type of return ('url' for link only or 'text' for "Back to all [term]" text).
 * @return string The generated URL or text.
 */
function get_back_to_archive_link( $return_type = 'url' ) {
    // Get the terms for the post in the 'services' taxonomy
    $terms = get_the_terms( get_the_ID(), 'services' );

    if ( !empty( $terms ) && !is_wp_error( $terms ) ) {
        $term = $terms[0]; // Use the first term for the single page
        $term_name = ucwords( $term->name ); // Capitalize the term name
        $term_slug = $term->slug;

        // Construct the URL in the form /services/[term]
        $archive_url = home_url( '/services/' . $term_slug );

        // Return URL or formatted text based on $return_type
        if ( $return_type === 'url' ) {
            return esc_url( $archive_url );
        } else {
            return 'Back to all ' . $term_name;
        }
    }

    return ''; // Return empty if no term is found
}

