/**
 * Helper function to determine zone data based on score
 */
function get_score_zone_data($score) {
    if ($score >= 0.0 && $score <= 4.9) {
        return array(
            'emoji' => '🔴',
            'zone' => 'At Risk',
            'message' => 'Major HR gaps—urgent attention needed',
            'color' => '#e53e3e'
        );
    } else if ($score >= 5.0 && $score <= 7.4) {
        return array(
            'emoji' => '🟠',
            'zone' => 'Unstable',
            'message' => 'Working—but exposed in key areas',
            'color' => '#dd6b20'
        );
    } else if ($score >= 7.5 && $score <= 8.9) {
        return array(
            'emoji' => '🟡',
            'zone' => 'Solid',
            'message' => 'Good shape—ready to strengthen',
            'color' => '#d69e2e'
        );
    } else if ($score >= 9.0 && $score <= 10.0) {
        return array(
            'emoji' => '🟢',
            'zone' => 'Strategic',
            'message' => 'Strong HR—ready to scale and optimise',
            'color' => '#38a169'
        );
    }
    
    // Default fallback
    return array(
        'emoji' => '⚪',
        'zone' => 'Unknown',
        'message' => 'Unable to determine score zone',
        'color' => '#718096'
    );
}

